import * as React from "react";
import {
  Card,
  Box,
  BlockStack,
  InlineStack,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { RecommendationItem, type RecommendationItemType } from "./RecommendationItem";

export const DEFAULT_AI_RECOMMENDATIONS: RecommendationItemType[] = [
  {
    id: "fbt-bundle",
    title: "Launch 'Frequently Bought Together' Bundle",
    description:
      "Pair your best-selling product with 1-2 complementary items to offer a 1-click bundle discount on the product page.",
    liftBadge: {
      text: "+12.5%",
      tone: "success",
    },
    actionType: "create_fbt",
    primaryAction: {
      label: "Launch bundle",
    },
    secondaryAction: {
      label: "Preview",
    },
  },
  {
    id: "shipping-protection",
    title: "Add Shipping Protection Add-On ($1.99)",
    description:
      "A zero-inventory micro-upsell with 95%+ profit margin. Over 34% of shoppers opt in for package guarantee.",
    liftBadge: {
      text: "+$1.85",
      tone: "success",
    },
    actionType: "create_addon",
    primaryAction: {
      label: "Add protection",
    },
    secondaryAction: {
      label: "Configure",
    },
  },
  {
    id: "post-purchase-funnel",
    title: "Enable 1-Click Post-Purchase Funnel",
    description:
      "Show a limited-time 20% off offer right after payment before the thank you page with zero friction (1-click tokenized charge).",
    liftBadge: {
      text: "+8.4%",
      tone: "success",
    },
    actionType: "enable_post_purchase",
    primaryAction: {
      label: "Enable funnel",
    },
    secondaryAction: {
      label: "Customize",
    },
  },
];

export type AiRecommendationsPropsType = {
  title?: string;
  subtitle?: string;
  badgeLabel?: string;
  items?: RecommendationItemType[];
  onItemAction?: (item: RecommendationItemType) => void;
  onItemDismiss?: (id: string) => void;
  onDismiss?: () => void;
};

export function AiRecommendations({
  title = "AI recommendations",
  subtitle = "Order history basket mining and high-impact revenue opportunities for your store.",
  badgeLabel = "AI strategy copilot",
  items = DEFAULT_AI_RECOMMENDATIONS,
  onItemAction,
  onItemDismiss,
  onDismiss,
}: AiRecommendationsPropsType) {
  return (
    <Card
      heading={title}
      description={subtitle}
      actions={
        <InlineStack gap="small-200" alignItems="center">
          {badgeLabel && <Badge tone="info">{badgeLabel}</Badge>}
          {onDismiss && (
            <Button
              variant="tertiary"
              icon="x"
              accessibilityLabel="Dismiss recommendations"
              onClick={onDismiss}
            />
          )}
        </InlineStack>
      }
    >
      {items.length > 0 ? (
        <BlockStack gap="small-300">
          {items.map((item) => (
            <RecommendationItem
              key={item.id}
              item={item}
              onAction={onItemAction}
              onDismiss={onItemDismiss}
            />
          ))}
        </BlockStack>
      ) : (
        <Box
          padding="base"
          borderRadius="large"
          background="bg-surface-secondary"
        >
          <InlineStack justifyContent="center">
            <Text as="p" color="subdued">
              No active recommendations — check back as new orders come in.
            </Text>
          </InlineStack>
        </Box>
      )}
    </Card>
  );
}

import * as React from "react";
import { BlockStack, InlineStack, Button, Text, Box } from "@xco-agency/corex-ui";
import {
  AiRecommendations,
  DEFAULT_AI_RECOMMENDATIONS,
} from "./AiRecommendations";
import type { RecommendationItemType } from "./RecommendationItem";

export function AiRecommendationsExample() {
  const [items, setItems] = React.useState<RecommendationItemType[]>(
    DEFAULT_AI_RECOMMENDATIONS
  );
  const [isDismissed, setIsDismissed] = React.useState(false);

  const handleDismissItem = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
  };

  const handleReset = () => {
    setItems(DEFAULT_AI_RECOMMENDATIONS);
    setIsDismissed(false);
  };

  return (
    <BlockStack gap="base">
      {!isDismissed ? (
        <AiRecommendations
          items={items}
          onItemDismiss={handleDismissItem}
          onDismiss={() => setIsDismissed(true)}
        />
      ) : (
        <Box
          padding="base"
          background="bg-surface-secondary"
          borderRadius="large"
        >
          <InlineStack justifyContent="space-between" alignItems="center">
            <Text color="subdued">Recommendations card was dismissed.</Text>
            <Button variant="secondary" onClick={() => setIsDismissed(false)}>
              Restore Card
            </Button>
          </InlineStack>
        </Box>
      )}

      <InlineStack justifyContent="space-between" alignItems="center">
        <Text variant="bodySm" color="subdued">
          Interactive demo: {items.length} recommendations available.
        </Text>
        <Button variant="tertiary" onClick={handleReset}>
          Reset Recommendations
        </Button>
      </InlineStack>
    </BlockStack>
  );
}

import * as React from "react";
import {
  Box,
  InlineStack,
  Text,
  Badge,
  Button,
} from "@xco-agency/corex-ui";
import { RecommendationIllustration } from "./RecommendationIllustrations";

export type RecommendationItemType = {
  id: string;
  title: string;
  description: string;
  liftBadge: {
    text: string;
    tone?: "success" | "info" | "warning" | "neutral";
  };
  actionType: "create_fbt" | "create_addon" | "enable_post_purchase" | "default";
  primaryAction?: {
    label: string;
    onClick?: () => void;
    variant?: "primary" | "secondary" | "tertiary";
  };
  secondaryAction?: {
    label: string;
    onClick?: () => void;
  };
  media?: React.ReactNode;
  dismissable?: boolean;
};

export type RecommendationItemPropsType = {
  item: RecommendationItemType;
  onAction?: (item: RecommendationItemType) => void;
  onSecondaryAction?: (item: RecommendationItemType) => void;
  onDismiss?: (id: string) => void;
};

export function RecommendationItem({
  item,
  onAction,
  onSecondaryAction,
  onDismiss,
}: RecommendationItemPropsType) {
  const [loading, setLoading] = React.useState(false);
  const [activated, setActivated] = React.useState(false);

  const handlePrimaryClick = () => {
    if (item.primaryAction?.onClick) {
      item.primaryAction.onClick();
      return;
    }
    setLoading(true);
    setTimeout(() => {
      setLoading(false);
      setActivated(true);
      onAction?.(item);
    }, 500);
  };

  const handleSecondaryClick = () => {
    if (item.secondaryAction?.onClick) {
      item.secondaryAction.onClick();
      return;
    }
    onSecondaryAction?.(item);
  };

  return (
    <Box
      borderRadius="large"
      background="bg-surface-secondary"
      overflow="hidden"
      borderWidth="small-100"
      borderColor="border-subdued"
    >
      <div style={{ display: "flex", alignItems: "stretch", width: "100%" }}>
        {/* Full-height Media Column (Zero padding around image) */}
        <div
          style={{
            width: "96px",
            minWidth: "96px",
            display: "flex",
            alignItems: "stretch",
            flexShrink: 0,
            overflow: "hidden",
          }}
        >
          {item.media || <RecommendationIllustration actionType={item.actionType} />}
        </div>

        {/* Content Column */}
        <div
          style={{
            flex: 1,
            minWidth: 0,
            padding: "10px 12px",
            display: "flex",
            flexDirection: "column",
            gap: "6px",
            justifyContent: "center",
          }}
        >
          {/* Header Row: Base Heading + Trend Badge + Dismiss Button */}
          <div
            style={{
              display: "flex",
              alignItems: "flex-start",
              justifyContent: "space-between",
              gap: "8px",
            }}
          >
            <div
              style={{
                display: "flex",
                alignItems: "center",
                gap: "6px",
                flexWrap: "wrap",
                flex: 1,
                minWidth: 0,
              }}
            >
              <Text as="h3" variant="base" heading>
                {item.title}
              </Text>

              {item.liftBadge && (
                <div style={{ flexShrink: 0 }}>
                  <Badge
                    tone={item.liftBadge.tone || "success"}
                    icon="arrow-up-right"
                  >
                    {item.liftBadge.text}
                  </Badge>
                </div>
              )}
            </div>

            {item.dismissable !== false && onDismiss && (
              <div style={{ flexShrink: 0, marginBlockStart: -4, marginInlineEnd: -4 }}>
                <Button
                  variant="tertiary"
                  icon="x"
                  accessibilityLabel={`Dismiss ${item.title}`}
                  onClick={() => onDismiss(item.id)}
                />
              </div>
            )}
          </div>

          {/* 2-line Clamped Description */}
          <Text as="p" color="subdued" variant="bodySm" lineClamp={2}>
            {item.description}
          </Text>

          {/* Action CTAs */}
          <InlineStack gap="small-200" alignItems="center">
            {item.primaryAction && (
              <Button
                variant={activated ? "secondary" : item.primaryAction.variant || "primary"}
                onClick={handlePrimaryClick}
                loading={loading}
                disabled={activated}
                icon={activated ? "check" : undefined}
              >
                {activated ? "Active" : item.primaryAction.label}
              </Button>
            )}

            {item.secondaryAction && (
              <Button
                variant="tertiary"
                onClick={handleSecondaryClick}
              >
                {item.secondaryAction.label}
              </Button>
            )}
          </InlineStack>
        </div>
      </div>
    </Box>
  );
}

export {
  AiRecommendations,
  DEFAULT_AI_RECOMMENDATIONS,
} from "./AiRecommendations";
export type { AiRecommendationsPropsType } from "./AiRecommendations";
export { RecommendationItem } from "./RecommendationItem";
export type {
  RecommendationItemType,
  RecommendationItemPropsType,
} from "./RecommendationItem";
export {
  RecommendationIllustration,
  FrequentlyBoughtTogetherIllustration,
  ShippingProtectionIllustration,
  PostPurchaseFunnelIllustration,
} from "./RecommendationIllustrations";
export { AiRecommendationsExample } from "./AiRecommendationsExample";
